"""Turn alerts on and off: a no_agent cron job that runs one check round a minute and posts what changed.

The job is created through the public cronjob_manage tool, so it goes through Hermes' normal approvals and
shows up in `hermes cron list` like any other job the user can pause or remove.
"""

from __future__ import annotations

import json
from pathlib import Path

from .service import Watch

JOB_NAME = "homelab-watch alerts"
SCRIPT_NAME = "homelab_watch_tick.py"
SCHEDULE = "every 1m"
PLUGIN_DIR = Path(__file__).resolve().parent

_SCRIPT = '''\
# Generated by the homelab-watch plugin (`/homelab alerts on`). Safe to delete with `/homelab alerts off`.
# One read-only check round; prints only incidents that opened or resolved, so quiet minutes send nothing.
from importlib import util
spec = util.spec_from_file_location("homelab_watch_cron_tick", {entry!r})
tick = util.module_from_spec(spec)
spec.loader.exec_module(tick)
raise SystemExit(tick.main({plugin_dir!r}, {targets!r}, {state!r}))
'''


def render_script(watch: Watch) -> str:
    return _SCRIPT.format(entry=str(PLUGIN_DIR / "cron_tick.py"),
                          plugin_dir=str(PLUGIN_DIR), targets=str(watch.targets_path),
                          state=str(watch.store.path))


def _call(dispatch, args: dict) -> dict:
    try:
        return json.loads(dispatch("cronjob_manage", args))
    except (TypeError, ValueError):
        return {"success": False, "error": "cronjob_manage returned no JSON"}


def find_job(dispatch) -> dict | None:
    listing = _call(dispatch, {"action": "list"})
    return next((j for j in listing.get("jobs", []) if j.get("name") == JOB_NAME), None)


def enable(dispatch, watch: Watch, scripts_dir: Path, deliver: str = "") -> str:
    watch.check()  # fail now on a broken targets file; anything already down is announced by the first tick
    scripts_dir.mkdir(parents=True, exist_ok=True)
    (scripts_dir / SCRIPT_NAME).write_text(render_script(watch), encoding="utf-8")
    existing = find_job(dispatch)
    if existing:
        return f"Alerts are already on (job {existing.get('job_id')}). `/homelab alerts off` to stop them."
    args = {"action": "create", "name": JOB_NAME, "schedule": SCHEDULE, "script": SCRIPT_NAME,
            "no_agent": True, "prompt": ""}
    if deliver:
        args["deliver"] = deliver
    result = _call(dispatch, args)
    if not result.get("success"):
        return f"Could not create the alerts job: {result.get('error') or result}"
    where = result.get("deliver") or deliver or "this chat"
    return f"Alerts on: checking every minute, posting changes to {where} (job {result.get('job_id')})."


def disable(dispatch, scripts_dir: Path) -> str:
    job = find_job(dispatch)
    (scripts_dir / SCRIPT_NAME).unlink(missing_ok=True)
    if not job:
        return "Alerts were not on."
    result = _call(dispatch, {"action": "remove", "job_id": job["job_id"]})
    if not result.get("success"):
        return f"Could not remove job {job['job_id']}:{result.get('error') or result}"
    return "Alerts off. Checks still run whenever you ask."


def status(dispatch) -> str:
    job = find_job(dispatch)
    if not job:
        return "Alerts are off. `/homelab alerts on [telegram|discord|…]` to turn them on."
    return f"Alerts are on: job {job.get('job_id')}, {job.get('schedule')}, next run {job.get('next_run_at')}."
